/**
 * Veylora — Dynamic Data Loader
 * 
 * Loads product, category, settings, and collection data from static JSON
 * files generated by scripts/build.js. Provides safe DOM rendering helpers
 * that never inject untrusted content via innerHTML.
 */

(function () {
  'use strict';

  const DATA_DIR = 'data';
  const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

  let cache = {};
  let cacheTimestamps = {};

  // --- Affiliate URL validation (Amazon.in only) ---
  const AMAZON_IN_HOSTS = new Set(['amazon.in', 'www.amazon.in']);

  function isValidAmazonInUrl(url) {
    if (!url || typeof url !== 'string') return false;
    try {
      const parsed = new URL(url);
      return AMAZON_IN_HOSTS.has(parsed.hostname);
    } catch {
      return false;
    }
  }

  function sanitizeAffiliateUrl(url) {
    if (!isValidAmazonInUrl(url)) return null;
    return url;
  }

  // --- Safe DOM helpers ---
  function escapeHtml(text) {
    if (text == null) return '';
    const div = document.createElement('div');
    div.textContent = String(text);
    return div.innerHTML;
  }

  function setText(el, text) {
    if (!el) return;
    el.textContent = text == null ? '' : String(text);
  }

  function setAttr(el, name, value) {
    if (!el) return;
    if (value == null) {
      el.removeAttribute(name);
    } else {
      el.setAttribute(name, String(value));
    }
  }

  function createElement(tag, attrs = {}, children = []) {
    const el = document.createElement(tag);
    Object.entries(attrs).forEach(([name, value]) => {
      if (name === 'className') {
        el.className = value;
      } else if (name === 'dataset') {
        Object.entries(value).forEach(([k, v]) => el.dataset[k] = v);
      } else if (name === 'text') {
        el.textContent = value;
      } else if (name === 'html') {
        // Intentionally NOT used — safe text only
        el.textContent = value;
      } else {
        el.setAttribute(name, String(value));
      }
    });
    children.forEach((child) => {
      if (child instanceof Node) el.appendChild(child);
      else if (typeof child === 'string') el.appendChild(document.createTextNode(child));
    });
    return el;
  }

  // --- Data fetching ---
  async function fetchJson(filename) {
    const now = Date.now();
    if (
      cache[filename] &&
      cacheTimestamps[filename] &&
      now - cacheTimestamps[filename] < CACHE_DURATION
    ) {
      return cache[filename];
    }

    const url = `${DATA_DIR}/${filename}?t=${now}`;
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) {
      throw new Error(`Failed to load ${filename}: ${res.status}`);
    }
    const data = await res.json();
    cache[filename] = data;
    cacheTimestamps[filename] = now;
    return data;
  }

  // --- Public API ---
  const loadData = {
    async getCategories() {
      return fetchJson('categories.json');
    },
    async getProducts() {
      return fetchJson('products.json');
    },
    async getSettings() {
      return fetchJson('settings.json');
    },
    async getFeatured() {
      return fetchJson('featured.json');
    },
    async getCollections() {
      return fetchJson('collections.json');
    },
    async getCategory(slug) {
      return fetchJson(`category-${slug}.json`);
    },
  };

  // --- Product card rendering (safe, no innerHTML) ---
  function renderProductCard(product, options = {}) {
    const {
      showCategory = true,
      showPrice = true,
      linkText = 'View on Amazon.in',
    } = options;

    const article = createElement('article', {
      className:
        'group bg-surface-container-low rounded overflow-hidden flex flex-col shadow-md transition-all duration-300 hover:shadow-2xl hover:bg-surface-container',
      'data-product-id': product.id,
    });

    // Image wrapper
    const imageWrap = createElement('div', {
      className: 'relative aspect-[4/5] bg-surface-container-high overflow-hidden',
    });

    const img = createElement('img', {
      className:
        'w-full h-full object-cover img-fade transition-transform duration-500 group-hover:scale-105',
      loading: 'lazy',
      decoding: 'async',
      src: product.image_url || 'assets/images/favicon.png',
      alt: escapeHtml(product.name || 'Product'),
    });

    // Category badge
    if (showCategory && product.category_name) {
      const badge = createElement(
        'span',
        {
          className:
            'absolute top-3 left-3 bg-surface-container-lowest/80 backdrop-blur-md px-2 py-0.5 rounded font-metadata text-metadata text-on-surface-variant',
          text: escapeHtml(product.category_name),
        },
        []
      );
      imageWrap.appendChild(badge);
    }

    // Featured badge
    if (product.is_featured) {
      const featuredBadge = createElement(
        'div',
        {
          className:
            'absolute bottom-3 right-3 bg-surface-container-lowest/90 px-2 py-0.5 rounded flex items-center gap-1',
        },
        [
          createElement('span', {
            className: 'material-symbols-outlined text-primary text-[14px]',
            text: 'bolt',
          }),
          createElement('span', {
            className: 'font-metadata text-metadata text-primary font-bold',
            text: 'Prime',
          }),
        ]
      );
      imageWrap.appendChild(featuredBadge);
    }

    article.appendChild(imageWrap);

    // Content
    const content = createElement('div', {
      className: 'p-space-md flex flex-col justify-between flex-1',
    });

    const info = createElement('div', {});

    if (product.brand) {
      const brandEl = createElement(
        'span',
        {
          className:
            'font-label-caps-sm text-label-caps-sm text-outline uppercase tracking-wider block mb-0.5',
          text: escapeHtml(product.brand),
        },
        []
      );
      info.appendChild(brandEl);
    }

    const titleEl = createElement(
      'h4',
      {
        className: 'font-headline-sm text-headline-sm text-on-surface mt-0.5 line-clamp-1',
        text: escapeHtml(product.name || 'Untitled'),
      },
      []
    );
    info.appendChild(titleEl);

    if (showPrice) {
      const priceWrap = createElement('div', {
        className: 'flex items-baseline gap-2 mt-space-xs',
      });
      const priceEl = createElement(
        'span',
        {
          className: 'font-headline-sm text-headline-sm text-primary',
          text: `₹${Number(product.price || 0).toLocaleString('en-IN')}`,
        },
        []
      );
      priceWrap.appendChild(priceEl);
      if (product.original_price && product.original_price > product.price) {
        const origEl = createElement(
          'span',
          {
            className:
              'font-metadata text-metadata text-outline line-through',
            text: `₹${Number(product.original_price).toLocaleString('en-IN')}`,
          },
          []
        );
        priceWrap.appendChild(origEl);
      }
      info.appendChild(priceWrap);
    }

    content.appendChild(info);

    // CTA link — only render valid Amazon.in affiliate URLs
    const affiliateUrl = sanitizeAffiliateUrl(product.affiliate_url);
    if (affiliateUrl) {
      const cta = createElement(
        'a',
        {
          className:
            'mt-space-md w-full py-2.5 rounded bg-primary text-on-primary font-label-caps-sm text-label-caps-sm tracking-[0.16em] uppercase flex items-center justify-center gap-space-xs hover:bg-primary-fixed transition-colors active:scale-95 shadow-sm',
          href: affiliateUrl,
          target: '_blank',
          rel: 'sponsored noopener noreferrer',
          'aria-label': `View ${escapeHtml(product.name || 'product')} on Amazon.in`,
        },
        [
          createElement('span', { text: linkText }),
          createElement('span', {
            className: 'material-symbols-outlined text-[15px]',
            text: 'arrow_outward',
          }),
        ]
      );
      content.appendChild(cta);
    }

    article.appendChild(content);
    return article;
  }

  // --- Render products into a container ---
  function renderProducts(container, products, options = {}) {
    if (!container) return;
    container.innerHTML = '';

    if (!products || products.length === 0) {
      const empty = createElement(
        'div',
        {
          className: 'col-span-full text-center py-12',
        },
        [
          createElement('p', {
            className: 'text-outline text-sm',
            text: options.emptyMessage || 'No products found.',
          }),
        ]
      );
      container.appendChild(empty);
      return;
    }

    products.forEach((p) => {
      const card = renderProductCard(p, options);
      container.appendChild(card);
    });
  }

  // --- Loading state ---
  function showLoading(container, message = 'Loading…') {
    if (!container) return;
    container.innerHTML = '';
    const loader = createElement(
      'div',
      { className: 'col-span-full text-center py-12' },
      [
        createElement('p', {
          className: 'text-outline text-sm animate-pulse',
          text: message,
        }),
      ]
    );
    container.appendChild(loader);
  }

  // --- Export ---
  window.VeyloraData = {
    loadData,
    renderProductCard,
    renderProducts,
    showLoading,
    escapeHtml,
    setText,
    setAttr,
    createElement,
  };
})();
